-- Dados atuais da loja (3 produtos, definições e pagamento). Executar DEPOIS do 1-setup.sql.
-- Mantém os mesmos números (IDs) que o site já usa, para os carrinhos guardados nos telemóveis continuarem válidos.
begin;
select setval(pg_get_serial_sequence('public.produtos','id'), greatest((select coalesce(max(id),1) from public.produtos),1));
select setval(pg_get_serial_sequence('public.variantes','id'), greatest((select coalesce(max(id),1) from public.variantes),1));
commit;
